import glob

# Check for OpenClaw related files
opencaw_files = glob.glob('/home/bob/*openclaw*', recursive=False) + glob.glob('/home/bob/.hermes/*openclaw*', recursive=False)
print("OpenClaw related files:")
for f in opencaw_files:
    print(f"  {f}")

# Check for OpenClaw processes
opencaw_processes = []
try:
    import subprocess
    result = subprocess.run(['ps', 'aux'], capture_output=True, text=True)
    for line in result.stdout.split('\n'):
        if 'openclaw' in line.lower() and 'grep' not in line:
            opencaw_processes.append(line.strip())
except Exception as e:
    opencaw_processes.append(f"Error checking processes: {e}")

print("\nOpenClaw processes:")
if opencaw_processes:
    for p in opencaw_processes:
        print(f"  {p}")
else:
    print("  None found")

# Check for OpenClaw configurations or data
opencaw_configs = glob.glob('/home/bob/.openclaw*', recursive=False) + glob.glob('/home/bob/*openclaw*/config*', recursive=False)
print("\nOpenClaw configs:")
for c in opencaw_configs:
    print(f"  {c}")

# Check for any pending OpenClaw tasks
opencaw_tasks = glob.glob('/home/bob/*openclaw*/tasks*', recursive=False) + glob.glob('/home/bob/*openclaw*/*todo*', recursive=False)
print("\nOpenClaw task files:")
for t in opencaw_tasks:
    print(f"  {t}")"}

